"r2q1rk1/1bpp1ppp/p1n2n2/1pb1p3/P3P3/1BNP1N2/1PP2PPP/R1BQ1RK1 b - -":{"variation":"arkhangelsk-variation","moves":[{"uci":"c6a5","notes":[{"text":"Black's knight attacks your bishop, wanting to trade it off and double your pawns.","original":"In responses to this, black wants to get rid of white's most active piece, the light-squared bishop. Black will also double white's pawns.","ideas":[{"type":"purpose","from":"a5","relation":"attacks","targets":["b3"]},{"type":"threat","side":"black","move":"a5b3"}]}]}]},
"r2q1rk1/1bpp1ppp/p4n2/npb1p3/P3P3/1BNP1N2/1PP2PPP/R1BQ1RK1 w - -":{"variation":"arkhangelsk-variation","moves":[{"uci":"a4b5","book":true,"notes":[{"text":"You stick to your plan and take the b-pawn anyway, opening the a-file for your rook.","original":"White stick to their main plan and takes the b-pawn anyway, opening up the file for their rook.","ideas":[{"type":"structure","side":"white","features":[{"kind":"halfOpenFile","files":["a"]}]}]}]}]},
"r2q1rk1/1bpp1ppp/p4n2/nPb1p3/4P3/1BNP1N2/1PP2PPP/R1BQ1RK1 b - -":{"variation":"arkhangelsk-variation","moves":[{"uci":"a5b3","notes":[{"text":"Black also sticks to the plan and trades the knight for your bishop; you must retake.","original":"Black also sticks to their main plan and exchanges the knight for the bishop. White must take."}]}]},
"r2q1rk1/1bpp1ppp/p4n2/1Pb1p3/4P3/1nNP1N2/1PP2PPP/R1BQ1RK1 w - -":{"variation":"arkhangelsk-variation","moves":[{"uci":"c2b3","book":true,"notes":[{"text":"Retaking doubles your b-pawns.","original":"White now doubles up their pawns.","ideas":[{"type":"structure","side":"white","features":[{"kind":"doubledPawns","files":["b"]}]}]}]}]},
"r2q1rk1/1bpp1ppp/p4n2/1Pb1p3/4P3/1PNP1N2/1P3PPP/R1BQ1RK1 b - -":{"variation":"arkhangelsk-variation","moves":[{"uci":"a6b5","notes":[{"text":"Black wins the pawn back and opens the a-file for a rook trade.","original":"Black takes back the pawn and opens up the opportunity for a rook exchange.","ideas":[{"type":"purpose","from":"a8","relation":"attacks","targets":["a1"]}]}]}]},
