"r2qr1k1/1bp1bppp/p1np1n2/1p2p3/3PP3/1BP2N1P/PP3PP1/RNBQR1K1 w - -":{"variation":"closed-ruy-lopez-zaitsev-variation","moves":[{"uci":"b1d2","book":true,"notes":[{"text":"Your knight develops and backs up the e4 pawn Black is aiming at.","generated":true,"ideas":[{"type":"purpose","from":"d2","relation":"defends","targets":["e4"]}]}],"games":[12,77,314,1321,3877]},{"uci":"a2a4","games":[1,9,23,99,378]},{"uci":"f3g5","games":[3,16,71,232,711]}]},
